import type { BankQuestion } from "@/lib/bank";

/** Biotechnology: Principles and Applications (Biology (NEET)): 90 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-biotechnology-1","question":"The first restriction endonuclease to be isolated, in 1968, was:","options":["Taq polymerase","BamHI","EcoRI","Hind II"],"answer":3,"explanation":"Hind II, which always cuts DNA at a particular point by recognising a specific sequence of six base pairs, was the first restriction endonuclease isolated. EcoRI was characterised later.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biotechnology-2","question":"Agarose, the matrix most commonly used for gel electrophoresis of DNA, is a natural polymer extracted from:","options":["Crustacean shells","Cotton fibres","Sea weeds","Bacterial cell walls"],"answer":2,"explanation":"Agarose is a natural polymer extracted from sea weeds. DNA fragments move through the agarose matrix according to their size.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biotechnology-3","question":"Bt cotton carries insecticidal protein genes taken from the bacterium:","options":["Thermus aquaticus","Bacillus thuringiensis","Agrobacterium tumefaciens","Escherichia coli"],"answer":1,"explanation":"Bt stands for Bacillus thuringiensis, whose cry genes code for insecticidal Bt toxin proteins.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biotechnology-4","question":"EcoRI recognises the palindromic sequence 5'-GAATTC-3' and cuts each strand between:","options":["G and A","T and C","A and T","A and A"],"answer":0,"explanation":"EcoRI cuts both strands between G and A, a little away from the centre of the palindrome, leaving single-stranded overhangs called sticky ends.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-5","question":"After gel electrophoresis, DNA fragments are made visible by staining with ethidium bromide followed by exposure to:","options":["UV radiation, under which they appear as bright orange bands","Visible light, under which they appear blue","Infrared light, under which they appear green","X-rays, under which they appear as dark spots"],"answer":0,"explanation":"DNA cannot be seen in visible light without staining; ethidium bromide-stained DNA shows bright orange bands under UV light.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-6","question":"In the E. coli cloning vector pBR322, the gene rop codes for:","options":["Resistance to ampicillin","The restriction site for EcoRI","Proteins involved in the replication of the plasmid","Resistance to tetracycline"],"answer":2,"explanation":"In pBR322, ampR and tetR are antibiotic resistance genes, ori is the origin of replication and rop codes for proteins involved in plasmid replication.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-7","question":"When a foreign DNA is inserted within the coding sequence of the enzyme β-galactosidase, the recombinant colonies grown with a chromogenic substrate:","options":["Produce blue colour","Do not produce colour (appear white)","Turn red","Fail to grow at all"],"answer":1,"explanation":"Insertion inactivates β-galactosidase (insertional inactivation), so recombinant colonies cannot act on the chromogenic substrate and stay colourless, while non-recombinant colonies turn blue.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-8","question":"The thermostable DNA polymerase used in the polymerase chain reaction is isolated from:","options":["Haemophilus influenzae","Bacillus thuringiensis","Thermus aquaticus","Escherichia coli"],"answer":2,"explanation":"Taq polymerase, from the bacterium Thermus aquaticus, stays active at the high temperatures used to denature DNA in each PCR cycle.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-9","question":"Rosie, the first transgenic cow (1997), produced milk that:","options":["Was free of lactose","Contained α-1-antitrypsin for treating emphysema","Contained human alpha-lactalbumin at 2.4 grams per litre","Contained human insulin"],"answer":2,"explanation":"Rosie produced human protein-enriched milk (2.4 g per litre) containing human alpha-lactalbumin, nutritionally more balanced for human babies than natural cow milk.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-10","question":"A nematode-resistant tobacco plant was developed using RNA interference against:","options":["Aphids feeding on tobacco leaves","Meloidogyne incognita, which infects tobacco roots","European corn borer","Cotton bollworm"],"answer":1,"explanation":"Nematode-specific genes were introduced via Agrobacterium vectors to produce both sense and anti-sense RNA; the dsRNA silenced the specific mRNA of Meloidogyne incognita, so the parasite could not survive in the transgenic host.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-11","question":"The proteins encoded by the genes cryIAc and cryIIAb control:","options":["Corn borer","Cotton bollworms","Mosquito larvae","Root-knot nematodes"],"answer":1,"explanation":"cryIAc and cryIIAb proteins control cotton bollworms, whereas cryIAb controls the corn borer.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-12","question":"Bt toxin does not kill the bacterium that makes it but kills insects that eat it because:","options":["It exists as an inactive protoxin that becomes active in the alkaline pH of the insect gut","It is activated by sunlight on the leaf surface","It becomes active only in the acidic pH of the insect gut","The bacterium carries an antidote gene that the insect lacks"],"answer":0,"explanation":"Bt protoxin crystals are solubilised by the alkaline pH of the insect gut; the active toxin binds the midgut epithelial cells and makes pores, causing swelling, lysis and death of the insect.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-13","question":"Insulin is synthesised as a prohormone. Which part of proinsulin is absent from mature insulin?","options":["The A chain","The C peptide","The B chain","The disulphide bridges"],"answer":1,"explanation":"Proinsulin contains an extra stretch, the C peptide, which is removed during maturation. In 1983 Eli Lilly made the A and B chains separately in E. coli and joined them by disulphide bonds.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-14","question":"The first clinical gene therapy, given in 1990 to a 4-year-old girl, treated a deficiency of the enzyme:","options":["Glucose-6-phosphate dehydrogenase","Phenylalanine hydroxylase","Adenosine deaminase (ADA)","β-galactosidase"],"answer":2,"explanation":"ADA deficiency affects the immune system. Lymphocytes from the patient's blood were cultured, a functional ADA cDNA was introduced with a retroviral vector, and the cells were returned to the patient.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-15","question":"The Ti plasmid of Agrobacterium tumefaciens is used as a cloning vector after it is modified so that it:","options":["Causes tumours more efficiently","Is no longer pathogenic but still delivers genes of interest into plants","Loses its ability to transfer DNA","Can replicate only in animal cells"],"answer":1,"explanation":"The tumour-inducing Ti plasmid normally transforms plant cells into tumours; the disarmed version still transfers DNA into plant cells but does not cause disease.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-16","question":"To make bacterial cells competent to take up recombinant DNA, they are treated with a specific concentration of a divalent cation and then given a heat shock. The cation and the heat-shock temperature are:","options":["Calcium; 94 °C","Calcium; 42 °C","Magnesium; 72 °C","Sodium; 37 °C"],"answer":1,"explanation":"Cells treated with Ca²⁺ are incubated with rDNA on ice, placed briefly at 42 °C (heat shock) and then put back on ice, which lets the DNA enter. Na⁺ is monovalent, and 72 °C or 94 °C are PCR temperatures.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-17","question":"In biotechnology, 'downstream processing' refers to:","options":["Separation and purification of the product after the biosynthetic stage","Growing the host in a small flask before scaling up","Isolation of the gene of interest","Transfer of rDNA into the host"],"answer":0,"explanation":"After biosynthesis the product must be separated and purified, then formulated with suitable preservatives and, for drugs, put through clinical trials and quality control.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-18","question":"According to NCERT, how many documented varieties of Basmati rice are grown in India?","options":["1000","200","27","50,000"],"answer":2,"explanation":"India has an estimated 200,000 varieties of rice, of which 27 documented varieties are Basmati. In 1997 an American company got patent rights on Basmati rice through the US Patent and Trademark Office.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-19","question":"How many of the following statements about restriction enzymes are correct?\n(i) Restriction endonucleases recognise specific palindromic nucleotide sequences.\n(ii) In EcoRI, the letter R is derived from the name of the strain (RY13).\n(iii) The Roman numeral in the name indicates the order in which the enzymes were isolated from that strain.\n(iv) EcoRI produces blunt ends without any overhang.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iii) are correct. EcoRI cuts away from the centre of the palindrome and leaves single-stranded sticky ends.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-20","question":"Arrange the steps of recombinant DNA technology in the correct order.\n(i) Ligation of the DNA fragment into a vector\n(ii) Fragmentation of DNA by restriction endonucleases\n(iii) Transfer of the recombinant DNA into the host\n(iv) Isolation of the desired DNA fragment\n(v) Culturing the host cells at large scale and extracting the product","options":["(iv), (ii), (i), (iii), (v)","(ii), (iv), (i), (iii), (v)","(ii), (i), (iv), (iii), (v)","(ii), (iv), (iii), (i), (v)"],"answer":1,"explanation":"After isolating DNA, it is cut, the desired fragment is isolated, ligated into a vector, the rDNA is transferred into the host, and the host is cultured at large scale to extract the product.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-21","question":"Assertion (A): In blue-white screening, recombinant colonies appear blue.\nReason (R): Insertion of foreign DNA into the coding region of β-galactosidase inactivates the enzyme.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"A is false but R is true: because the enzyme is inactivated, recombinant colonies cannot convert the chromogenic substrate and appear white (colourless); non-recombinants turn blue.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-22","question":"Match the tool with its source organism.\nList I: (A) Taq polymerase (B) Ti plasmid (C) cry genes (D) Hind II\nList II: (1) Haemophilus influenzae (2) Bacillus thuringiensis (3) Agrobacterium tumefaciens (4) Thermus aquaticus","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Taq polymerase comes from Thermus aquaticus, the Ti plasmid from Agrobacterium tumefaciens, cry genes from Bacillus thuringiensis and Hind II from Haemophilus influenzae.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-23","question":"How many of the following statements about PCR are correct?\n(i) Each cycle consists of denaturation, annealing and extension.\n(ii) Primers are small, chemically synthesised oligonucleotides complementary to regions of the template DNA.\n(iii) Repeated cycles can amplify a DNA segment to about a billion copies.\n(iv) A thermostable DNA polymerase extends the primers using the nucleotides provided.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Because Taq polymerase survives the high denaturation temperature, cycles can be repeated without adding fresh enzyme.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-24","question":"A PCR is started with 2 molecules of double-stranded target DNA. Assuming every cycle doubles the DNA, how many double-stranded copies are present after 5 cycles?","options":["32","128","64","10"],"answer":2,"explanation":"Copies = initial × 2ⁿ = 2 × 2⁵ = 2 × 32 = 64. The trap 32 forgets that there were two starting molecules.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-25","question":"How many of the following statements about transgenic animals are correct?\n(i) They are used to study how genes regulate normal physiology and development.\n(ii) Transgenic mice are being used to test the safety of the polio vaccine.\n(iii) α-1-antitrypsin produced by transgenic animals is used to treat phenylketonuria.\n(iv) Transgenic mice are being used to test the safety of the smallpox vaccine.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (ii) are correct. α-1-antitrypsin is used to treat emphysema, and NCERT cites testing of the polio vaccine on transgenic mice, not smallpox.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-26","question":"Assertion (A): Conventional methods such as serum and urine analysis cannot detect an infection early.\nReason (R): The concentration of the pathogen is very low in the early stage, before symptoms appear.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: by the time symptoms appear, the pathogen is already at high concentration. Very low amounts of nucleic acid can, however, be detected by amplifying them with PCR.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-27","question":"Which of the following is NOT a desirable feature of a cloning vector?","options":["A single recognition site for a commonly used restriction enzyme","An origin of replication (ori)","A selectable marker","Several recognition sites for the same restriction enzyme within the vector"],"answer":3,"explanation":"A vector needs a single recognition site for a given restriction enzyme; more than one site would cut the vector into several fragments and complicate cloning.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-28","question":"How many of the following statements about agarose gel electrophoresis are correct?\n(i) DNA fragments are negatively charged and move towards the anode.\n(ii) Larger fragments move farther than smaller ones.\n(iii) The separated bands are cut out from the gel and extracted, a step called elution.\n(iv) The DNA fragments are separated according to their size through the sieving effect of the agarose gel.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (iii) and (iv) are correct. The smaller the fragment, the farther it moves through the gel.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-29","question":"How many of the following statements are correct?\n(i) The Genetic Engineering Approval Committee (GEAC) decides on the validity of GM research and the safety of introducing GM organisms for public services.\n(ii) Biopiracy is the use of bio-resources by multinational companies without proper authorisation from the countries concerned or compensatory payment.\n(iii) The Indian Parliament has cleared the second amendment of the Indian Patents Bill.\n(iv) In 1997 an American company got patent rights on Basmati rice through the US Patent and Trademark Office.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct NCERT statements on the ethical issues of biotechnology.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-30","question":"A circular plasmid has three EcoRI sites and a linear DNA molecule also has three EcoRI sites. On complete digestion with EcoRI, the number of fragments produced is respectively:","options":["3 and 3","4 and 3","3 and 4","4 and 4"],"answer":2,"explanation":"Cutting a circle at n sites gives n pieces, while cutting a line at n sites gives n + 1 pieces, so 3 and 4.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-biotechnology-31", "question": "The enzyme that joins the cut ends of DNA fragments by sealing the sugar-phosphate backbone is:", "options": ["DNA ligase", "DNA polymerase", "Restriction endonuclease", "Exonuclease"], "answer": 0, "explanation": "DNA ligase joins DNA fragments; restriction endonucleases cut DNA, and DNA polymerase synthesises new strands.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-biotechnology-32", "question": "Restriction endonucleases are popularly called:", "options": ["Molecular glue", "Molecular scissors", "Molecular probes", "Molecular vectors"], "answer": 1, "explanation": "Restriction enzymes cut DNA at specific sequences, so they are called molecular scissors; ligase acts as the 'glue'.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-biotechnology-33", "question": "Large vessels in which raw materials are biologically converted into specific products by microbes, plant, animal or human cells are called:", "options": ["Incubators", "Centrifuges", "Bioreactors", "Electrophoresis tanks"], "answer": 2, "explanation": "Bioreactors provide optimal conditions such as temperature, pH, substrate, salts, vitamins and oxygen for producing the desired product on a large scale.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-biotechnology-34", "question": "Exonucleases differ from endonucleases in that exonucleases:", "options": ["Cut DNA only at palindromic sites", "Act only on RNA", "Join DNA fragments", "Remove nucleotides from the ends of DNA"], "answer": 3, "explanation": "Exonucleases remove nucleotides from the ends of DNA, whereas endonucleases make cuts at specific positions within the DNA.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-biotechnology-35", "question": "Selection of recombinants on the basis of the loss of a selectable marker's function, after foreign DNA has been inserted within it, is called:", "options": ["Insertional inactivation", "Transformation", "Transduction", "Elution"], "answer": 0, "explanation": "When foreign DNA is ligated within an antibiotic-resistance gene or the lacZ gene, that gene is inactivated; this insertional inactivation lets recombinants be told apart from non-recombinants.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-biotechnology-36", "question": "Genes for resistance to antibiotics such as ampicillin, chloramphenicol, tetracycline or kanamycin are useful selectable markers for E. coli because:", "options": ["They increase the copy number of the plasmid", "Normal E. coli cells do not carry resistance against these antibiotics", "They code for restriction enzymes", "They make the bacteria competent"], "answer": 1, "explanation": "Untransformed E. coli cells are killed by these antibiotics, so only cells that took up a vector carrying the resistance gene survive on antibiotic plates.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-biotechnology-37", "question": "In microinjection, the recombinant DNA is:", "options": ["Shot into plant cells on gold particles", "Delivered by a disarmed Agrobacterium", "Directly injected into the nucleus of an animal cell", "Taken up by bacteria after a heat shock"], "answer": 2, "explanation": "Microinjection injects recombinant DNA straight into the nucleus of an animal cell. Biolistics uses DNA-coated gold or tungsten particles, mainly for plants.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-biotechnology-38", "question": "In biolistics (gene gun), plant cells are bombarded with high-velocity micro-particles coated with DNA. These particles are made of:", "options": ["Silver or copper", "Iron or aluminium", "Silica or glass", "Gold or tungsten"], "answer": 3, "explanation": "Gold or tungsten micro-particles coated with DNA are fired into plant cells; the method is suitable for plants.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-biotechnology-39", "question": "ELISA, a technique used for early diagnosis of infection, is based on the principle of:", "options": ["Antigen–antibody interaction", "DNA–DNA hybridisation", "Amplification of nucleic acids", "Separation of DNA by charge"], "answer": 0, "explanation": "ELISA (enzyme-linked immunosorbent assay) detects antigens such as proteins or glycoproteins, or antibodies made against the pathogen, through antigen–antibody interaction.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-biotechnology-40", "question": "In 1983, Eli Lilly produced human insulin by recombinant DNA technology. They:", "options": ["Inserted the proinsulin gene and removed the C peptide in bacteria", "Prepared two DNA sequences for chains A and B, produced them separately in E. coli, and joined them by disulphide bonds", "Extracted insulin from the pancreas of transgenic pigs", "Expressed the complete insulin gene in tobacco plants"], "answer": 1, "explanation": "The A and B chains were made separately in E. coli from two synthetic DNA sequences, extracted, and combined by forming disulphide bonds to give human insulin.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-41", "question": "In detecting a mutated gene by hybridisation with a radioactive probe followed by autoradiography, the clone having the mutated gene:", "options": ["Appears as a dark band on the photographic film", "Appears only after PCR amplification", "Will not appear on the film, because the probe is not complementary to the mutated gene", "Glows under UV light"], "answer": 2, "explanation": "The single-stranded probe binds only to its complementary DNA; a mutated gene lacks full complementarity, so no signal appears for that clone on the film.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-42", "question": "The cohesive (sticky) ends produced by restriction enzymes are useful in recombinant DNA work because they:", "options": ["Prevent the vector from replicating", "Are methylated and resist further cutting", "Make DNA move faster in the gel", "Form hydrogen bonds with their complementary cut counterparts, which helps DNA ligase join the fragments"], "answer": 3, "explanation": "Single-stranded overhangs on fragments cut with the same enzyme pair up by hydrogen bonding; this stickiness helps DNA ligase seal them into recombinant DNA.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-43", "question": "Stirred-tank bioreactors are usually cylindrical or have a curved base in order to:", "options": ["Facilitate mixing of the reactor contents", "Reduce foam formation", "Allow light to reach the culture", "Prevent contamination"], "answer": 0, "explanation": "A cylindrical shape or curved base helps the stirrer mix the contents evenly and spread oxygen throughout the reactor.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-44", "question": "Besides initiating replication, the origin of replication (ori) in a vector also:", "options": ["Codes for antibiotic resistance", "Controls the copy number of the linked DNA", "Determines the size of the insert", "Carries the recognition site for EcoRI"], "answer": 1, "explanation": "Replication starts at ori, and the ori sequence also controls how many copies of the vector and its linked DNA are made; high copy number is wanted for many copies of the target DNA.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-45", "question": "Agrobacterium tumefaciens is used as a natural genetic engineer for plants. Which vectors, after being disarmed, play a similar role for animal cells?", "options": ["Bacteriophages", "Yeast plasmids", "Retroviruses", "Cosmids"], "answer": 2, "explanation": "Retroviruses can transform normal animal cells into cancerous cells; disarmed retroviruses are used to deliver desirable genes into animal cells.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-46", "question": "In gene therapy for ADA deficiency using lymphocytes, the patient needs periodic infusions of genetically engineered lymphocytes because:", "options": ["The ADA cDNA is lost after one cell division", "The ADA enzyme is destroyed by antibodies", "The retroviral vector kills the lymphocytes", "The engineered lymphocytes are not immortal"], "answer": 3, "explanation": "Lymphocytes grown in culture, given a functional ADA cDNA by a retroviral vector and returned to the patient do not live for ever, so the treatment must be repeated; inserting the gene into early embryonic stage cells could give a permanent cure.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-47", "question": "In RNA interference, the complementary double-stranded RNA that silences a specific mRNA may naturally originate from:", "options": ["Infection by viruses with RNA genomes or transposons that replicate through an RNA intermediate", "The host's ribosomal RNA", "Transfer RNA molecules", "Restriction enzymes"], "answer": 0, "explanation": "Natural sources of the dsRNA are RNA viruses and mobile genetic elements (transposons) that replicate via an RNA intermediate; the dsRNA binds and silences the target mRNA.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-48", "question": "According to NCERT, a bioreactor can process culture volumes of the order of:", "options": ["1–10 millilitres", "1–10 litres", "100–1000 litres", "1 million litres"], "answer": 2, "explanation": "Small-volume cultures cannot give appreciable yields, so bioreactors processing large volumes of about 100–1000 litres are used.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-49", "question": "How many of the following statements about Bt toxin are correct?\n(i) Bt toxin is effective against all insects, including aphids.\n(ii) The activated toxin binds to the surface of midgut epithelial cells and creates pores, causing cell swelling and lysis.\n(iii) The inactive protoxin is converted to the active form by the alkaline pH of the insect gut.\n(iv) The protein encoded by cryIAb controls corn borer.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(ii), (iii) and (iv) are correct. Bt toxin is insect-group specific, acting on lepidopterans, coleopterans and dipterans, not on all insects.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-50", "question": "Match the enzyme used in DNA isolation with its role.\nList I: (A) Lysozyme (B) Cellulase (C) Chitinase (D) Protease\nList II: (1) Breaks the fungal cell wall (2) Removes proteins associated with DNA (3) Breaks the bacterial cell wall (4) Breaks the plant cell wall", "options": ["A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1"], "answer": 1, "explanation": "Lysozyme digests bacterial walls, cellulase plant walls and chitinase fungal walls; proteases remove proteins such as histones and ribonuclease removes RNA.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-51", "question": "A foreign DNA is ligated into the BamHI site of the cloning vector pBR322, and E. coli cells are transformed. The recombinant transformants will:", "options": ["Grow on both ampicillin and tetracycline", "Grow on tetracycline but not on ampicillin", "Grow on ampicillin but not on tetracycline", "Grow on neither antibiotic"], "answer": 2, "explanation": "The BamHI site lies within the tetracycline-resistance gene, so the insert inactivates it; the ampicillin-resistance gene stays intact. Recombinants grow on ampicillin plates but die on tetracycline plates.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-52", "question": "Assertion (A): The restriction endonucleases of a bacterium do not cut the bacterium's own DNA.\nReason (R): The bacterium methylates its own DNA, which protects it from its restriction enzymes.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The restriction system of E. coli has two enzymes: one adds methyl groups to the cell's own DNA and the other cuts unmethylated foreign (phage) DNA. Methylation is why the host DNA is spared.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-53", "question": "How many of the following statements about cloning vectors are correct?\n(i) The origin of replication controls the copy number of the linked DNA.\n(ii) Any piece of DNA linked to the ori can be made to replicate within the host cells.\n(iii) Selectable markers help in identifying and eliminating non-transformants.\n(iv) Transformation is a procedure through which a piece of DNA is introduced into a host bacterium.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Ori starts replication and sets copy number, markers such as ampicillin resistance remove non-transformants, and transformation brings DNA into the host.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-54", "question": "Assume a DNA molecule with a random sequence in which all four bases are equally frequent. A restriction enzyme that recognises a specific 4-base-pair sequence would, on average, cut once in every:", "options": ["16 bp", "64 bp", "256 bp", "4096 bp"], "answer": 2, "explanation": "Each position matches with probability 1/4, so a 4-bp site occurs once in 4⁴ = 256 bp on average. A 6-bp site would occur once in 4⁶ = 4096 bp.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-55", "question": "How many of the following statements about molecular diagnosis are correct?\n(i) PCR is used to detect HIV in suspected AIDS patients.\n(ii) PCR is used to detect mutations in genes of suspected cancer patients.\n(iii) A probe is a single-stranded DNA or RNA tagged with a radioactive molecule.\n(iv) ELISA can detect an infection only through the presence of antigens, not antibodies.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iii) are correct. ELISA can detect either antigens or antibodies synthesised against the pathogen.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-56", "question": "Match the enzyme with its function.\nList I: (A) Restriction endonuclease (B) DNA ligase (C) Taq polymerase (D) Exonuclease\nList II: (1) Joins DNA fragments (2) Removes nucleotides from the ends of DNA (3) Cuts DNA at specific recognition sequences (4) Extends primers during PCR and stays active at high temperature", "options": ["A-3, B-4, C-1, D-2", "A-1, B-3, C-4, D-2", "A-3, B-1, C-2, D-4", "A-3, B-1, C-4, D-2"], "answer": 3, "explanation": "Restriction endonucleases cut at recognition sites, ligase joins fragments, thermostable Taq polymerase extends primers in PCR, and exonucleases trim nucleotides from DNA ends.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-57", "question": "Assertion (A): Host cells must be made competent before they can take up recombinant DNA.\nReason (R): DNA is a hydrophilic molecule and cannot pass through cell membranes.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Because hydrophilic DNA cannot cross membranes on its own, bacterial cells are first made competent, for example by treatment with divalent cations such as calcium, before transformation.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-58", "question": "All of the following statements about the vector pBR322 are correct EXCEPT:", "options": ["The PstI and PvuI sites lie within the tetracycline-resistance gene", "The BamHI and SalI sites lie within the tetracycline-resistance gene", "It has an origin of replication (ori)", "It carries the rop gene, which codes for proteins involved in plasmid replication"], "answer": 0, "explanation": "In pBR322 the PstI and PvuI sites lie within the ampicillin-resistance gene, while BamHI and SalI lie within the tetracycline-resistance gene.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-59", "question": "How many of the following statements about downstream processing are correct?\n(i) Drugs must be subjected to clinical trials before marketing.\n(ii) Strict quality control testing is required for each product.\n(iii) Downstream processing is identical for all biotechnological products.\n(iv) Formulation of the product with suitable preservatives is part of upstream processing.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only (i) and (ii) are correct. Downstream processing and quality control vary from product to product, and formulation with preservatives is part of downstream processing.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-60", "question": "Arrange the steps in isolating DNA from a cell in the correct order.\n(i) Removal of RNA by ribonuclease and of proteins by protease\n(ii) Breaking the cell wall with enzymes such as lysozyme, cellulase or chitinase\n(iii) Addition of chilled ethanol\n(iv) Spooling out the precipitated DNA as fine threads", "options": ["(i), (ii), (iii), (iv)", "(ii), (i), (iii), (iv)", "(ii), (iii), (i), (iv)", "(ii), (i), (iv), (iii)"], "answer": 1, "explanation": "The cell is first opened, then RNA and proteins are removed, then chilled ethanol precipitates the purified DNA, which is spooled out as threads.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-biotechnology-61","question":"In the name of the restriction enzyme EcoRI, the letter 'R' stands for:","options":["Restriction","The strain RY13 of the bacterium","Recognition sequence","Recombinant"],"answer":1,"explanation":"In EcoRI, 'E' comes from the genus Escherichia, 'co' from the species coli, 'R' from the strain RY13, and the Roman numeral I gives the order in which the enzyme was isolated from that strain.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biotechnology-62","question":"Cutting a separated DNA band out of an agarose gel and extracting the DNA from the gel piece is called:","options":["Spooling","Annealing","Elution","Transformation"],"answer":2,"explanation":"Elution recovers the purified DNA fragments from the gel so they can be used to build recombinant DNA. Spooling collects precipitated DNA threads, and annealing is the binding of primers in PCR.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biotechnology-63","question":"Plants, bacteria, fungi and animals whose genes have been altered by manipulation are called:","options":["Genetically modified organisms (GMOs)","Somaclones","Polyploids","Hybridomas"],"answer":0,"explanation":"Organisms whose genes have been changed by manipulation are called GMOs; Bt cotton is an example. Somaclones and polyploids arise without any deliberate gene transfer.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biotechnology-64","question":"During DNA isolation, purified DNA comes out of solution as fine threads after the addition of:","options":["Ethidium bromide","Calcium chloride","Chilled ethanol","Hot phenol"],"answer":2,"explanation":"Adding chilled ethanol makes the purified DNA precipitate as fine threads, which can be removed by spooling. Ethidium bromide stains DNA in gels, and calcium ions make cells competent.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-65","question":"The two core techniques that made modern biotechnology possible are:","options":["Tissue culture and hybridisation","Mutation breeding and polyploidy","Fermentation and distillation","Genetic engineering and bioprocess engineering"],"answer":3,"explanation":"Genetic engineering alters the chemistry of the genetic material, and bioprocess engineering keeps a sterile, contamination-free setting so that only the desired microbe or cell grows in large numbers.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-66","question":"Which of the following is NOT one of the three options listed for increasing food production?","options":["Agro-chemical based agriculture","Organic agriculture","Genetically engineered crop-based agriculture","Shifting (jhum) cultivation"],"answer":3,"explanation":"The three options are agro-chemical based agriculture, organic agriculture and genetically engineered crop-based agriculture. Shifting cultivation is not one of them.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-67","question":"Transgenic animals have been used to produce human alpha-1-antitrypsin, a protein used to treat:","options":["Cystic fibrosis","Emphysema","Phenylketonuria","Haemophilia"],"answer":1,"explanation":"Alpha-1-antitrypsin from transgenic animals is used to treat emphysema. Similar attempts are being made for phenylketonuria and cystic fibrosis, but the protein in question is meant for emphysema.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-68","question":"The safety of the polio vaccine is being tested on:","options":["Transgenic mice","Transgenic cows","Transgenic sheep","Transgenic pigs"],"answer":0,"explanation":"Transgenic mice are used to test the safety of vaccines, including the polio vaccine, before they are used on humans. If they prove reliable, they could replace monkeys for such testing.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-69","question":"Before recombinant DNA technology, the insulin used to treat diabetes was extracted from the pancreas of:","options":["Sheep and goats","Sharks","Slaughtered cattle and pigs","Horses"],"answer":2,"explanation":"Insulin was once extracted from the pancreas of slaughtered cattle and pigs. Being a foreign protein, it caused allergy or other reactions in some patients.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-70","question":"In the cloning vector pBR322, which pair of restriction sites lies within the tetracycline resistance gene (tetR)?","options":["PstI and PvuI","BamHI and SalI","PstI and SalI","EcoRI and PvuII"],"answer":1,"explanation":"In pBR322, BamHI and SalI sites lie in the tetR gene, while PstI and PvuI sites lie in the ampicillin resistance gene (ampR).","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-71","question":"The first recombinant DNA was made by linking an antibiotic resistance gene to a native plasmid of:","options":["Escherichia coli","Agrobacterium tumefaciens","Salmonella typhimurium","Bacillus thuringiensis"],"answer":2,"explanation":"Stanley Cohen and Herbert Boyer (1972) cut out an antibiotic resistance gene and linked it to a native plasmid of Salmonella typhimurium. E. coli later became the most common cloning host.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-72","question":"In 1963, two enzymes responsible for restricting the growth of bacteriophage in Escherichia coli were isolated. What did they do?","options":["One added methyl groups to DNA and the other cut DNA","Both joined DNA fragments","One unwound DNA and the other made primers","Both broke down viral RNA"],"answer":0,"explanation":"One enzyme methylated DNA and the other, a restriction endonuclease, cut DNA. Methylation protects the bacterium's own DNA from its restriction enzymes.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-73","question":"About how many restriction enzymes have been isolated, and from how many bacterial strains?","options":["About 90, from 23 strains","More than 9,000, from over 2,300 strains","About 300, from 50 strains","More than 900, from over 230 strains"],"answer":3,"explanation":"More than 900 restriction enzymes have been isolated from over 230 strains of bacteria, each recognising a different sequence.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-74","question":"Some plasmids are present as only one or two copies per cell. Others may have about:","options":["500 to 1,000 copies per cell","5 to 10 copies per cell","15 to 100 copies per cell","More than 10,000 copies per cell"],"answer":2,"explanation":"Plasmid copy number ranges from one or two to 15 to 100 copies per cell. Bacteriophages, being numerous per cell, have even higher copy numbers of their genome.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-75","question":"The Bt toxin gene cryIAb protects crops against:","options":["Cotton bollworms","Corn borer","Aphids","Root-knot nematodes"],"answer":1,"explanation":"The protein encoded by cryIAb controls the corn borer, while cryIAc and cryIIAb proteins control cotton bollworms. Nematodes are controlled by RNA interference, not by Bt toxin.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-76","question":"About how many varieties of rice are estimated to exist in India alone?","options":["27","2,000","20,000","200,000"],"answer":3,"explanation":"India has about 200,000 rice varieties, one of the richest rice diversities in the world. The figure 27 is the number of documented Basmati varieties.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-77","question":"In 1997, an American company obtained patent rights on Basmati rice through the:","options":["World Trade Organization","US Patent and Trademark Office","Genetic Engineering Approval Committee","Food and Agriculture Organization"],"answer":1,"explanation":"The patent was granted by the US Patent and Trademark Office. The 'new' variety had in fact been derived by crossing Indian farmers' Basmati with semi-dwarf varieties.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-78","question":"The European Federation of Biotechnology (EFB) defines biotechnology as:","options":["The integration of natural science and organisms, cells, parts thereof and molecular analogues for products and services","The use of microbes only for making curd, bread and wine","The chemical synthesis of drugs without the use of living cells","The breeding of crop plants by selection and hybridisation"],"answer":0,"explanation":"The EFB definition covers both traditional and modern molecular biotechnology. Fermentation is only one part of biotechnology, and conventional breeding does not by itself fit the definition.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-79","question":"Match the item with what it is linked to.\nList I: (A) Rosie (B) Alpha-1-antitrypsin (C) Meloidogyne incognita (D) Adenosine deaminase deficiency\nList II: (1) Emphysema (2) RNA interference (3) Milk enriched with human alpha-lactalbumin (4) First clinical gene therapy, 1990","options":["A-3, B-2, C-1, D-4","A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4"],"answer":3,"explanation":"The transgenic cow Rosie gave milk containing human alpha-lactalbumin. Alpha-1-antitrypsin treats emphysema, the nematode Meloidogyne incognita was controlled by RNA interference, and ADA deficiency was the target of the first gene therapy in 1990.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-80","question":"How many of the following are the critical research areas of biotechnology?\n(i) Providing the best catalyst as an improved organism, usually a microbe, or a pure enzyme\n(ii) Creating optimal conditions through engineering for the catalyst to act\n(iii) Downstream processing technologies to purify the protein or organic compound\n(iv) Breeding new crop varieties only by hybridisation and selection","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"The three critical research areas are (i), (ii) and (iii). Conventional breeding by hybridisation and selection is not one of them.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-81","question":"How many of the following statements about genetically modified crops are correct?\n(i) They have been made more tolerant to abiotic stresses such as cold, drought, salt and heat.\n(ii) They have reduced reliance on chemical pesticides.\n(iii) They have helped to reduce post-harvest losses.\n(iv) They have increased the efficiency of mineral use by plants.\n(v) Bt crops are protected against all insect pests, so no other pest management is ever needed.","options":["Only two","Only three","Only four","All five"],"answer":2,"explanation":"Statements (i) to (iv) are correct. Bt toxins act on particular insect groups, such as lepidopterans, coleopterans and dipterans, not on all insects.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-82","question":"How many of the following statements about restriction enzymes are correct?\n(i) The first letter of the name comes from the genus and the next two letters from the species of the bacterium.\n(ii) The Roman numeral shows the order in which the enzymes were isolated from that strain.\n(iii) Restriction enzymes belong to a larger class of enzymes called nucleases.\n(iv) A restriction endonuclease inspects the length of a DNA sequence and binds to the DNA at its recognition sequence.\n(v) EcoRI produces blunt ends.","options":["Only two","Only four","Only three","All five"],"answer":1,"explanation":"Statements (i) to (iv) are correct. EcoRI cuts a little away from the centre of the palindrome on both strands, leaving sticky ends, not blunt ends.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-83","question":"Assertion (A): A cloning vector should preferably have a single recognition site for the restriction enzyme being used.\nReason (R): More than one recognition site within the vector would produce several fragments, which complicates gene cloning.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. A single site means the vector opens at one place only, so R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-84","question":"Assertion (A): A continuous culture system gives a larger biomass and higher yields of the desired protein than a batch culture.\nReason (R): In continuous culture, used medium is drained out and fresh medium added, so the cells stay in their physiologically most active log (exponential) phase.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. Keeping the cells in the log phase is exactly why continuous culture gives more biomass, so R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-85","question":"Match the term with its description.\nList I: (A) Biopiracy (B) Elution (C) Spooling (D) Transformation\nList II: (1) Introducing a piece of DNA into a host bacterium (2) Collecting precipitated DNA threads (3) Use of bio-resources by multinational companies without proper authorisation or compensation (4) Extracting a separated DNA fragment from a gel piece","options":["A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1","A-1, B-4, C-2, D-3","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Biopiracy is unauthorised, uncompensated use of bio-resources; elution recovers DNA from a gel; spooling collects precipitated DNA; transformation introduces DNA into a host bacterium.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-86","question":"From the following list, how many are components of a bioreactor?\nAgitator system, oxygen delivery system, foam control system, temperature control system, pH control system, sampling ports, gel electrophoresis tank","options":["Four","Five","Seven","Six"],"answer":3,"explanation":"The first six are bioreactor components; sampling ports let small volumes of culture be withdrawn periodically. A gel electrophoresis tank is used to separate DNA fragments and is not part of a bioreactor.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-87","question":"How many of the following statements about adenosine deaminase (ADA) deficiency are correct?\n(i) It is caused by deletion of the gene for adenosine deaminase.\n(ii) In some children it can be cured by bone marrow transplantation.\n(iii) Enzyme replacement therapy is completely curative.\n(iv) In gene therapy, functional ADA cDNA is introduced into the patient's cultured lymphocytes using a retroviral vector.\n(v) A permanent cure may be possible if the gene from marrow cells producing ADA is introduced into cells at early embryonic stages.","options":["Only two","Only three","All five","Only four"],"answer":3,"explanation":"Statements (i), (ii), (iv) and (v) are correct. Neither bone marrow transplantation nor enzyme replacement therapy is completely curative.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-88","question":"A palindrome in DNA reads the same on both strands when each is read in the 5' to 3' direction. How many of the following top-strand sequences (5' to 3') are palindromic?\nGAATTC, GGATCC, AAGCTT, GTTAAC, GACTTC, CAGCTG","options":["Three","Four","Five","Six"],"answer":2,"explanation":"For each sequence, write the complementary strand and read it 5' to 3'. GAATTC, GGATCC, AAGCTT, GTTAAC and CAGCTG are their own reverse complements; the reverse complement of GACTTC is GAAGTC, so it is not palindromic.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-89","question":"A foreign DNA is ligated into the PstI site of pBR322 and E. coli cells are transformed. How do the recombinant transformants behave?","options":["They grow on both ampicillin and tetracycline","They grow on ampicillin but not on tetracycline","They grow on tetracycline but not on ampicillin","They grow on neither antibiotic"],"answer":2,"explanation":"The PstI site lies in the ampR gene, so the insert inactivates ampicillin resistance while tetracycline resistance stays intact. Non-recombinant plasmids would grow on both antibiotics.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-90","question":"How many of the following statements about biopiracy and the Basmati patent are correct?\n(i) Biopiracy is the use of bio-resources by multinational companies without proper authorisation from the countries and people concerned and without compensatory payment.\n(ii) The Indian Parliament has cleared the second amendment of the Indian Patents Bill, which takes such issues into consideration.\n(iii) Industrialised nations are richer in biodiversity and traditional knowledge than developing nations.\n(iv) The patented 'new' Basmati had been derived by crossing Indian farmers' Basmati with semi-dwarf varieties.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iv) are correct. Industrialised nations are rich financially but poor in biodiversity and traditional knowledge, whereas developing and underdeveloped nations are rich in both.","difficulty":"very-hard","source":"NEET pattern"},
];

export default questions;
